'use client';

import { useEffect, useState } from 'react';
import { API_BASE } from './api';

export interface TrainAvailableClass {
  code: string;
  name: string;
}

export interface VerifiedCoachEntry {
  code: string;
  name: string;
  category: string;
  position: number;
}

export interface VerifiedTrainCoachMetadata {
  trainNo: string;
  trainName: string | null;
  rakeType: string | null;
  hasPantry: boolean | null;
  availableClasses: TrainAvailableClass[];
  coaches: VerifiedCoachEntry[];
  totalCoaches: number;
  source: string | null;
  isVerified: true;
}

export interface PnrCoachMergeInput {
  rakeType?: string | null;
  hasPantry?: boolean | null;
  availableClasses?: TrainAvailableClass[] | null;
}

export interface MergedTrainCoachFields {
  rakeType?: string;
  hasPantry?: boolean;
  availableClasses?: TrainAvailableClass[];
}

const CANONICAL_CLASS_ORDER: ReadonlyArray<TrainAvailableClass> = [
  { code: '1A', name: 'AC First Class' },
  { code: '2A', name: 'AC 2 Tier' },
  { code: '3A', name: 'AC 3 Tier' },
  { code: '3E', name: 'AC 3 Economy' },
  { code: 'SL', name: 'Sleeper' },
  { code: 'EC', name: 'Exec. Chair Car' },
  { code: 'CC', name: 'AC Chair Car' },
  { code: '2S', name: 'Second Sitting' },
];

const PASSENGER_CLASS_CODES = new Set(CANONICAL_CLASS_ORDER.map((c) => c.code));
const STRUCTURAL_END_CATEGORIES = new Set(['ENG', 'LOCO', 'EOG', 'SLR', 'LPR', 'HCP', 'GEN', 'GS']);

export function normalizeTrainNoForCoaches(trainNo?: string | null): string | null {
  const clean = typeof trainNo === 'string' ? trainNo.trim() : String(trainNo ?? '').trim();
  if (!/^\d{4,5}$/.test(clean)) return null;
  if (/^0+$/.test(clean)) return null;
  return clean.padStart(5, '0');
}

function inferCoachCategory(rawCode: string, rawCategory: string, rawType: string): string {
  const cat = rawCategory.trim().toUpperCase();
  const code = rawCode.trim().toUpperCase();
  const type = rawType.trim().toLowerCase();

  if (cat === 'PC' || code === 'PC' || type === 'pantry') return 'PC';
  if (cat && (PASSENGER_CLASS_CODES.has(cat) || STRUCTURAL_END_CATEGORIES.has(cat) || cat === 'HA')) {
    return cat;
  }
  if (code === 'L' || code === 'LOCO' || code === 'ENG' || type.includes('loco') || type.includes('engine')) return 'ENG';
  if (code === 'EOG' || code === 'SLR' || code === 'LPR' || code === 'SLRD' || code === 'DL1' || code === 'DL2') return 'SLR';
  if (code === 'GEN' || code === 'GS' || code === 'UR' || /^D\d+$/.test(code) && type.includes('general')) return 'GS';
  if (/^HA\d*/.test(code)) return 'HA';
  if (/^H\d+/.test(code)) return '1A';
  if (/^A\d+/.test(code)) return '2A';
  if (/^B\d+/.test(code)) return '3A';
  if (/^M\d+/.test(code)) return '3E';
  if (/^S\d+/.test(code)) return 'SL';
  if (/^E\d+/.test(code)) return 'EC';
  if (/^C\d+/.test(code)) return 'CC';
  if (/^D\d+/.test(code)) return '2S';
  return cat || 'GEN';
}

function inferCoachLabel(code: string, category: string, rawName: string): string {
  if (rawName.trim()) return rawName.trim();
  switch (category) {
    case 'ENG':
    case 'LOCO':
      return 'Locomotive';
    case 'SLR':
    case 'EOG':
    case 'LPR':
      return 'Luggage & Brake Van';
    case 'GS':
    case 'GEN':
      return 'General Unreserved';
    case 'PC':
      return 'Pantry Car';
    case 'HA':
      return 'First AC & Second AC';
    case '1A':
      return 'AC First Class';
    case '2A':
      return 'AC 2-Tier';
    case '3A':
      return 'AC 3-Tier';
    case '3E':
      return 'AC 3 Economy';
    case 'SL':
      return 'Sleeper Class';
    case 'EC':
      return 'Exec. Chair Car';
    case 'CC':
      return 'AC Chair Car';
    case '2S':
      return 'Second Sitting';
    default:
      return `Coach ${code}`;
  }
}

/**
 * CT-09A pure extractor:
 * - Handles both warm DB responses (with explicit has_pantry & available_classes)
 *   and first cold provider responses (coaches[] + rake_type only).
 * - Rejects null, empty, failed, or malformed payloads.
 * - Never fabricates hasPantry=false unless coach list completeness is authoritatively proven.
 */
export function extractVerifiedCoachMetadata(rawResponseOrData: unknown): VerifiedTrainCoachMetadata | null {
  if (!rawResponseOrData || typeof rawResponseOrData !== 'object') return null;
  const envelope = rawResponseOrData as Record<string, any>;

  if (envelope.success === false) return null;

  const payload =
    envelope.data && typeof envelope.data === 'object' && !Array.isArray(envelope.data)
      ? (envelope.data as Record<string, any>)
      : envelope;

  if (!Array.isArray(payload.coaches) || payload.coaches.length === 0) {
    return null;
  }

  const validCoaches: VerifiedCoachEntry[] = [];
  let foundPantry = false;
  let hasStructuralEndCar = false;
  const foundClassCodes = new Set<string>();

  for (let i = 0; i < payload.coaches.length; i++) {
    const raw = payload.coaches[i];
    if (!raw || typeof raw !== 'object') continue;

    const rawCode = typeof raw.code === 'string' ? raw.code.trim() : '';
    const rawCat = typeof raw.category === 'string'
      ? raw.category.trim()
      : (typeof raw.class === 'string' ? raw.class.trim() : '');
    const rawType = typeof raw.type === 'string' ? raw.type.trim() : '';
    const rawName = typeof raw.name === 'string' ? raw.name.trim() : '';

    if (!rawCode && !rawCat) continue;

    const code = (rawCode || rawCat).toUpperCase();
    const category = inferCoachCategory(code, rawCat, rawType);
    const pos =
      typeof raw.position === 'number' && Number.isFinite(raw.position) && raw.position > 0
        ? Math.round(raw.position)
        : validCoaches.length + 1;

    validCoaches.push({
      code,
      name: inferCoachLabel(code, category, rawName),
      category,
      position: pos,
    });

    if (category === 'PC' || code === 'PC' || rawType.toLowerCase() === 'pantry') {
      foundPantry = true;
    }
    if (STRUCTURAL_END_CATEGORIES.has(category) || code === 'L' || code === 'LOCO' || code === 'EOG' || code === 'SLR' || code === 'LPR') {
      hasStructuralEndCar = true;
    }
    if (PASSENGER_CLASS_CODES.has(category)) {
      foundClassCodes.add(category);
    } else if (category === 'HA') {
      foundClassCodes.add('1A');
      foundClassCodes.add('2A');
    }
  }

  if (validCoaches.length === 0) return null;

  const rakeRaw = payload.rake_type ?? payload.rakeType;
  const rakeType = typeof rakeRaw === 'string' && rakeRaw.trim() ? rakeRaw.trim() : null;

  const explicitClassesRaw = payload.available_classes ?? payload.availableClasses;
  let availableClasses: TrainAvailableClass[] = [];
  if (Array.isArray(explicitClassesRaw) && explicitClassesRaw.length > 0) {
    availableClasses = explicitClassesRaw
      .filter((c: any) => c && typeof c.code === 'string' && c.code.trim() && typeof c.name === 'string' && c.name.trim())
      .map((c: any) => ({ code: c.code.trim().toUpperCase(), name: c.name.trim() }));
  }
  if (availableClasses.length === 0) {
    availableClasses = CANONICAL_CLASS_ORDER.filter((cls) => foundClassCodes.has(cls.code));
  }

  const declaredTotal =
    typeof payload.total_coaches === 'number' && Number.isFinite(payload.total_coaches) && payload.total_coaches > 0
      ? payload.total_coaches
      : null;

  let hasPantry: boolean | null = null;
  if (typeof payload.has_pantry === 'boolean') {
    hasPantry = payload.has_pantry;
  } else if (typeof payload.hasPantry === 'boolean') {
    hasPantry = payload.hasPantry;
  } else if (foundPantry) {
    hasPantry = true;
  } else {
    const isAuthoritativelyComplete =
      declaredTotal !== null &&
      validCoaches.length >= declaredTotal &&
      hasStructuralEndCar &&
      foundClassCodes.size > 0;
    hasPantry = isAuthoritativelyComplete ? false : null;
  }

  const rawTrainNo = payload.train_no ?? payload.trainNo ?? '';
  const normTrainNo = normalizeTrainNoForCoaches(String(rawTrainNo)) || String(rawTrainNo).trim();
  const rawTrainName = payload.train_name ?? payload.trainName;
  const trainName = typeof rawTrainName === 'string' && rawTrainName.trim() ? rawTrainName.trim() : null;

  const rawSource = payload.source;
  const source = typeof rawSource === 'string' && rawSource.trim() ? rawSource.trim() : null;

  return {
    trainNo: normTrainNo,
    trainName,
    rakeType,
    hasPantry,
    availableClasses,
    coaches: validCoaches,
    totalCoaches: declaredTotal ?? validCoaches.length,
    source,
    isVerified: true,
  };
}

/**
 * Pure non-clobbering merger for TrainStatsCard props.
 * Never accepts unverified mock data; only merges verified API metadata when PNR response lacks a field.
 */
export function mergeTrainCoachMetadata(
  pnrFields: PnrCoachMergeInput,
  verifiedCoachMeta: VerifiedTrainCoachMetadata | null | undefined
): MergedTrainCoachFields {
  const verified = verifiedCoachMeta && verifiedCoachMeta.isVerified ? verifiedCoachMeta : null;

  const rakeType =
    (typeof pnrFields.rakeType === 'string' && pnrFields.rakeType.trim() ? pnrFields.rakeType.trim() : undefined) ??
    (verified?.rakeType ?? undefined);

  const hasPantry =
    typeof pnrFields.hasPantry === 'boolean'
      ? pnrFields.hasPantry
      : (typeof verified?.hasPantry === 'boolean' ? verified.hasPantry : undefined);

  const availableClasses =
    Array.isArray(pnrFields.availableClasses) && pnrFields.availableClasses.length > 0
      ? pnrFields.availableClasses
      : (verified && verified.availableClasses.length > 0 ? verified.availableClasses : undefined);

  return { rakeType, hasPantry, availableClasses };
}

// ── Session-level per-train request deduplication (StrictMode & remount safe) ──
const resolvedCoachCache = new Map<string, VerifiedTrainCoachMetadata>();
const inFlightCoachRequests = new Map<string, Promise<VerifiedTrainCoachMetadata | null>>();

export function clearVerifiedTrainCoachCache(): void {
  resolvedCoachCache.clear();
  inFlightCoachRequests.clear();
}

export function getInFlightTrainCoachCount(): number {
  return inFlightCoachRequests.size;
}

export type CoachPayloadFetcher = (trainNo: string) => Promise<unknown>;

async function defaultCoachFetcher(trainNo: string): Promise<unknown> {
  const res = await fetch(`${API_BASE}/trains/coaches/${encodeURIComponent(trainNo)}`, {
    method: 'GET',
    headers: { Accept: 'application/json' },
  });
  if (!res.ok) return null;
  return res.json();
}

/**
 * Deduplicated, non-aborting shared fetch per canonical trainNo.
 * - Completed verified results are cached for the browser session.
 * - Failed / null responses are NOT cached so subsequent retries can succeed.
 * - Individual component unmounts do not abort a shared request needed by another mount.
 */
export async function fetchVerifiedTrainCoaches(
  trainNo?: string | null,
  fetcher: CoachPayloadFetcher = defaultCoachFetcher
): Promise<VerifiedTrainCoachMetadata | null> {
  const key = normalizeTrainNoForCoaches(trainNo);
  if (!key) return null;

  const cached = resolvedCoachCache.get(key);
  if (cached) return cached;

  const existing = inFlightCoachRequests.get(key);
  if (existing) return existing;

  const promise = (async (): Promise<VerifiedTrainCoachMetadata | null> => {
    try {
      const raw = await fetcher(key);
      const parsed = extractVerifiedCoachMetadata(raw);
      if (parsed) {
        resolvedCoachCache.set(key, parsed);
      }
      return parsed;
    } catch {
      return null;
    } finally {
      inFlightCoachRequests.delete(key);
    }
  })();

  inFlightCoachRequests.set(key, promise);
  return promise;
}

export interface UseVerifiedTrainCoachesResult {
  coachMeta: VerifiedTrainCoachMetadata | null;
  coachLoading: boolean;
}

/**
 * Non-blocking React hook for PNR pages.
 * Uses local cancellation guard (never aborts shared in-flight request) and
 * rejects stale responses if trainNo changes before resolution.
 */
export function useVerifiedTrainCoaches(
  trainNo?: string | null,
  enabled: boolean = true
): UseVerifiedTrainCoachesResult {
  const normalized = normalizeTrainNoForCoaches(trainNo);
  const [coachMeta, setCoachMeta] = useState<VerifiedTrainCoachMetadata | null>(() =>
    normalized ? (resolvedCoachCache.get(normalized) ?? null) : null
  );
  const [coachLoading, setCoachLoading] = useState<boolean>(false);

  useEffect(() => {
    if (!normalized) {
      setCoachMeta(null);
      setCoachLoading(false);
      return;
    }

    const cached = resolvedCoachCache.get(normalized);
    if (cached) {
      setCoachMeta(cached);
      setCoachLoading(false);
      return;
    }

    if (!enabled) {
      setCoachMeta(null);
      setCoachLoading(false);
      return;
    }

    let cancelled = false;
    setCoachMeta(null);
    setCoachLoading(true);

    fetchVerifiedTrainCoaches(normalized).then((result) => {
      if (cancelled) return;
      setCoachMeta(result);
      setCoachLoading(false);
    });

    return () => {
      cancelled = true;
    };
  }, [normalized, enabled]);

  return { coachMeta, coachLoading };
}
