'use client';

import React, { useRef, useState } from 'react';
import {
  Train, Calendar, Clock, MapPin, Download, Share2, X,
  CheckCircle2, AlertTriangle, ShieldCheck, User, QrCode
} from 'lucide-react';
import { clsx } from 'clsx';
import { toPng } from 'html-to-image';
import { shareToWhatsApp, showDOMToast } from '@/utils/share';
import { getPNRLink } from '@/config/domains';
import { parsePnrPassengerSeat } from '@/utils/pnrPassengerParser';
import { formatPnrForShare, formatShareUrlForPnr } from '@/lib/pnrPrivacyAndFreshness';

interface TravelBoardingPassModalProps {
  isOpen: boolean;
  onClose: () => void;
  pnr: string;
  trainNo: string;
  trainName: string;
  source: string;
  sourceCode?: string;
  destination: string;
  destinationCode?: string;
  journeyDate: string;
  departureTime?: string;
  arrivalTime?: string;
  platform?: string;
  chartStatus?: string;
  passengers: Array<{
    name: string;
    booking_status: string;
    current_status: string;
    coach?: string;
    coupe?: string;
    berth?: string | number;
    berth_type?: string;
  }>;
}

export const TravelBoardingPassModal: React.FC<TravelBoardingPassModalProps> = ({
  isOpen,
  onClose,
  pnr,
  trainNo,
  trainName,
  source,
  sourceCode,
  destination,
  destinationCode,
  journeyDate,
  departureTime,
  arrivalTime,
  platform,
  chartStatus,
  passengers
}) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [downloading, setDownloading] = useState(false);
  const [includeFullPnrInShare, setIncludeFullPnrInShare] = useState(false);

  if (!isOpen) return null;

  const isChartPrepared = !!chartStatus &&
    chartStatus.toUpperCase().includes('PREPARED') &&
    !chartStatus.toUpperCase().includes('NOT PREPARED');

  const isAllConfirmed = passengers.length > 0 && passengers.every(p => {
    const s = (p.current_status || '').toUpperCase();
    return s.includes('CNF') || s.includes('CONFIRM') || s.includes('CONFIRMED');
  });

  const handleDownload = async () => {
    if (!cardRef.current) return;
    setDownloading(true);
    try {
      showDOMToast('Generating your Travel Pass image...', 'info');
      const dataUrl = await toPng(cardRef.current, {
        backgroundColor: '#09090b',
        pixelRatio: 2
      });

      const link = document.createElement('a');
      link.download = `Trayago-Boarding-Pass-${pnr}.png`;
      link.href = dataUrl;
      link.click();
      showDOMToast('Travel Pass downloaded to gallery!', 'success');
    } catch (err) {
      console.error('Failed to export boarding pass:', err);
      showDOMToast('Could not save image. Please screenshot your pass.', 'error');
    } finally {
      setDownloading(false);
    }
  };

  const handleShareWhatsApp = () => {
    const sharePnr = formatPnrForShare(pnr, includeFullPnrInShare);
    const link = formatShareUrlForPnr(pnr, getPNRLink(pnr), includeFullPnrInShare);
    const paxSummary = passengers.map((p, idx) => {
      const parsed = parsePnrPassengerSeat(p);
      const seatInfo = parsed.coach && parsed.berth
        ? `Coach ${parsed.coach}${parsed.coupe ? ` (${parsed.coupe})` : ''}, Berth ${parsed.berth}${parsed.berthType ? ` (${parsed.berthType})` : ''}${parsed.isRac ? ' [RAC]' : ''}`
        : parsed.isCnf
        ? 'Confirmed'
        : (p.current_status || 'Unknown');
      return `• Pax ${idx + 1}: *${p.name || `Passenger ${idx + 1}`}* ➔ ${seatInfo}`;
    }).join('\n');

    const msg = [
      `🎫 *TRAYAGO TRAVEL PASS*`,
      `━━━━━━━━━━━━━━━━━━━━`,
      `🎟️ *PNR:* ${sharePnr}`,
      `🚆 *Train:* ${trainName} (${trainNo})`,
      `📅 *Date:* ${journeyDate}${departureTime ? ` · Dep: ${departureTime}` : ''}`,
      `📍 *Route:* ${source} (${sourceCode || ''}) ➔ ${destination} (${destinationCode || ''})`,
      platform ? `🚉 *Platform:* ${platform}` : null,
      `📊 *Chart:* ${isChartPrepared ? '✅ Chart Prepared' : '⏳ Chart Not Prepared'}`,
      `\n👥 *Passengers:*`,
      paxSummary,
      `\n━━━━━━━━━━━━━━━━━━━━`,
      `🔗 *Live Track Pass:*`,
      link
    ].filter(Boolean).join('\n');

    shareToWhatsApp(msg);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="relative w-full max-w-md bg-zinc-950 border border-zinc-800 rounded-3xl shadow-2xl overflow-hidden max-h-[92vh] flex flex-col">
        {/* Modal Top Bar */}
        <div className="flex items-center justify-between px-5 py-3 border-b border-zinc-800/80 bg-zinc-900/50">
          <div className="flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
            <span className="text-xs font-black uppercase tracking-widest text-zinc-300">
              Travel Boarding Pass
            </span>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-full text-zinc-400 hover:text-white hover:bg-zinc-800 transition-colors cursor-pointer"
          >
            <X size={18} />
          </button>
        </div>

        {/* Scrollable Pass Area */}
        <div className="overflow-y-auto p-4 sm:p-5 flex-1">
          {/* Exportable Boarding Pass Card */}
          <div
            ref={cardRef}
            className="relative bg-gradient-to-b from-zinc-900 via-zinc-950 to-zinc-900 border border-zinc-800 rounded-3xl p-5 text-white shadow-2xl space-y-4"
          >
            {/* Pass Header */}
            <div className="flex items-center justify-between border-b border-zinc-800/80 pb-3">
              <div>
                <div className="flex items-center gap-1.5">
                  <Train size={14} className="text-blue-400" />
                  <span className="text-xs font-black uppercase tracking-wider text-blue-400">
                    TRAYAGO EXPRESS
                  </span>
                </div>
                <p className="text-[10px] text-zinc-400 uppercase tracking-widest">
                  Official Travel Boarding Card
                </p>
              </div>
              <div className="text-right">
                <span className="text-[9px] font-mono uppercase text-zinc-500 tracking-widest block">
                  PNR NUMBER
                </span>
                <span className="text-sm font-mono font-black text-white tracking-widest">
                  {pnr}
                </span>
              </div>
            </div>

            {/* Train details */}
            <div className="bg-zinc-900/80 border border-zinc-800 rounded-2xl p-3.5 space-y-1">
              <span className="text-[9px] font-black uppercase tracking-widest text-zinc-400">
                TRAIN DETAILS
              </span>
              <div className="flex items-center justify-between">
                <h3 className="text-base font-black text-white tracking-tight">
                  {trainName}
                </h3>
                <span className="px-2 py-0.5 rounded-md bg-blue-500/20 text-blue-400 font-mono font-bold text-xs">
                  #{trainNo}
                </span>
              </div>
            </div>

            {/* Route Stations */}
            <div className="grid grid-cols-2 gap-3 bg-zinc-900/40 p-3 rounded-2xl border border-zinc-800/60">
              <div>
                <span className="text-[9px] font-black uppercase tracking-widest text-zinc-400">
                  DEPARTURE
                </span>
                <h4 className="text-sm font-black text-white truncate">{source}</h4>
                <p className="text-xs font-mono font-bold text-blue-400 mt-0.5">
                  {departureTime || 'Time unavailable'}
                </p>
                <p className="text-[10px] text-zinc-400">{journeyDate}</p>
                <span className="inline-block mt-1 text-[9px] font-bold text-zinc-400 bg-zinc-800/80 px-2 py-0.5 rounded">
                  {platform ? `Platform ${platform}` : 'Platform TBD'}
                </span>
              </div>

              <div className="text-right">
                <span className="text-[9px] font-black uppercase tracking-widest text-zinc-400">
                  DESTINATION
                </span>
                <h4 className="text-sm font-black text-white truncate">{destination}</h4>
                <p className="text-xs font-mono font-bold text-emerald-400 mt-0.5">
                  {arrivalTime || 'Time unavailable'}
                </p>
                <p className="text-[10px] text-zinc-400">Scheduled Run</p>
                <span className="inline-block mt-1 text-[9px] font-bold text-zinc-400 bg-zinc-800/80 px-2 py-0.5 rounded">
                  Direct Arrival
                </span>
              </div>
            </div>

            {/* Passenger List */}
            <div className="space-y-2">
              <span className="text-[9px] font-black uppercase tracking-widest text-zinc-400">
                PASSENGER SEAT ALLOTMENT ({passengers.length})
              </span>
              <div className="space-y-1.5">
                {passengers.map((p, idx) => {
                  const cur = (p.current_status || '').trim();
                  const parsed = parsePnrPassengerSeat(p);
                  const { isCnf, coach, coupe, berth, berthTypeDesc } = parsed;

                  return (
                    <div
                      key={idx}
                      className="flex items-center justify-between p-2.5 rounded-xl bg-zinc-900/60 border border-zinc-800/60 text-xs"
                    >
                      <div className="flex items-center gap-2">
                        <span className="w-5 h-5 rounded-full bg-zinc-800 flex items-center justify-center font-mono text-[10px] font-bold text-zinc-400">
                          {idx + 1}
                        </span>
                        <div>
                          <p className="font-bold text-white text-xs leading-tight">
                            {p.name || `Passenger ${idx + 1}`}
                          </p>
                          <p className="text-[9px] text-zinc-400 font-mono">
                            {isCnf ? 'Confirmed Booking' : cur}
                          </p>
                        </div>
                      </div>

                      <div className="text-right">
                        {coach && berth ? (
                          <div className="px-2.5 py-1 rounded-lg bg-emerald-500/15 border border-emerald-500/30 text-emerald-400 font-mono font-bold text-xs inline-block">
                            {coach}{coupe ? ` (${coupe})` : ''} / {berth}
                            {berthTypeDesc && <span className="block text-[8px] font-normal">{berthTypeDesc}</span>}
                          </div>
                        ) : (
                          <div className="px-2 py-0.5 rounded-lg bg-amber-500/15 border border-amber-500/30 text-amber-400 font-mono font-bold text-[11px] inline-block">
                            {cur || 'WL'}
                          </div>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Chart Status Banner */}
            <div className={clsx(
              "p-2.5 rounded-xl border flex items-center justify-between text-xs",
              isChartPrepared
                ? "bg-emerald-500/10 border-emerald-500/30 text-emerald-400"
                : "bg-amber-500/10 border-amber-500/30 text-amber-400"
            )}>
              <div className="flex items-center gap-1.5">
                {isChartPrepared ? <CheckCircle2 size={13} /> : <Clock size={13} />}
                <span className="font-bold uppercase tracking-wider text-[10px]">
                  {isChartPrepared ? 'IRCTC Chart Prepared' : 'Chart In Queue'}
                </span>
              </div>
              <span className="text-[9px] font-mono">
                {isChartPrepared ? 'Berths Final' : '~4 hrs prior'}
              </span>
            </div>

            {/* Perforated Divider */}
            <div className="relative flex items-center py-1">
              <div className="w-3 h-3 rounded-full bg-zinc-950 -ml-6 border border-zinc-800" />
              <div className="flex-1 border-t border-dashed border-zinc-700/80 mx-1" />
              <div className="w-3 h-3 rounded-full bg-zinc-950 -mr-6 border border-zinc-800" />
            </div>

            {/* Footer verification tag */}
            <div className="flex items-center justify-between pt-1 text-[9px] text-zinc-500">
              <div className="flex items-center gap-1">
                <ShieldCheck size={11} className="text-emerald-500" />
                <span>Verified by Trayago Railway Core</span>
              </div>
              <span className="font-mono">www.trayago.in</span>
            </div>
          </div>
        </div>

        {/* Action Buttons + CT-06B (GAP-P2-06) Privacy-First Share Toggle */}
        <div className="p-4 border-t border-zinc-800/80 bg-zinc-900/60 space-y-3">
          <label
            data-pnr-share-privacy-toggle="true"
            className="flex items-center justify-between gap-2 text-[11px] text-zinc-300 cursor-pointer select-none px-1"
          >
            <span className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={includeFullPnrInShare}
                onChange={(e) => setIncludeFullPnrInShare(e.target.checked)}
                className="rounded border-zinc-600 bg-zinc-800 text-blue-500 focus:ring-blue-500 cursor-pointer"
              />
              <span className="font-semibold">Include full PNR in share</span>
            </span>
            <span className="font-mono text-[10px] text-zinc-400">
              {formatPnrForShare(pnr, includeFullPnrInShare)}
            </span>
          </label>
          <div className="flex flex-col sm:flex-row gap-2.5">
          <button
            type="button"
            onClick={handleDownload}
            disabled={downloading}
            className="flex-1 inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl bg-blue-600 hover:bg-blue-500 text-white font-bold text-xs tracking-wide transition-all cursor-pointer shadow-lg active:scale-95 disabled:opacity-60"
          >
            <Download size={14} />
            <span>{downloading ? 'Saving Image...' : 'Save Pass (PNG)'}</span>
          </button>

          <button
            type="button"
            onClick={handleShareWhatsApp}
            className="flex-1 inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs tracking-wide transition-all cursor-pointer shadow-lg active:scale-95"
          >
            <Share2 size={14} />
            <span>Share to WhatsApp</span>
          </button>
          </div>
        </div>
      </div>
    </div>
  );
};
